I'll create a Pulumi ComponentResource that encapsulates the S3 bucket, RDS instance, and IAM role with environment-aware configuration.

```typescript
// components/AppInfrastructure.ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as random from "@pulumi/random";

export interface AppInfrastructureArgs {
    environment: "dev" | "prod";
    region: string;
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
    enableReplication?: boolean; // Prod only: cross-region replication
    replicationRegion?: string;
    oidcProviderArn?: string; // Prod: IRSA (IAM Roles for Service Accounts)
    oidcProviderUrl?: string;
    tags: Record<string, string>;
}

export class AppInfrastructure extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly dbInstance: aws.rds.Instance;
    public readonly serviceAccountRole: aws.iam.Role;
    public readonly dbConnectionString: pulumi.Output<string>;
    public readonly dbPassword: pulumi.Output<string>;

    constructor(name: string, args: AppInfrastructureArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:components:AppInfrastructure", name, {}, opts);

        const defaultTags = {
            Environment: args.environment,
            ManagedBy: "Pulumi",
            ...args.tags,
        };

        // =========================================================================
        // S3 Bucket: Versioning + Encryption + Public Access Block
        // =========================================================================
        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            bucket: `${name}-assets-${args.environment}`,
            tags: defaultTags,
        }, { parent: this });

        // Block all public access (Acceptance Criteria #1)
        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // Enable versioning (Acceptance Criteria #1)
        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, { parent: this });

        // Server-side encryption (AES-256) (Acceptance Criteria #1)
        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-encryption`, {
            bucket: this.bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "AES256",
                },
                bucketKeyEnabled: true,
            }],
        }, { parent: this });

        // Prod-only: Cross-region replication to us-west-2
        if (args.environment === "prod" && args.enableReplication && args.replicationRegion) {
            const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Action: "sts:AssumeRole",
                        Effect: "Allow",
                        Principal: { Service: "s3.amazonaws.com" },
                    }],
                }),
                tags: defaultTags,
            }, { parent: this });

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replicationRole.id,
                policy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Action: [
                            "s3:GetReplicationConfiguration",
                            "s3:ListBucket",
                        ],
                        Effect: "Allow",
                        Resource: [this.bucket.arn],
                    }, {
                        Action: [
                            "s3:GetObjectVersionForReplication",
                            "s3:GetObjectVersionAcl",
                            "s3:GetObjectVersionTagging",
                        ],
                        Effect: "Allow",
                        Resource: [pulumi.interpolate`${this.bucket.arn}/*`],
                    }, {
                        Action: [
                            "s3:ReplicateObject",
                            "s3:ReplicateDelete",
                            "s3:ReplicateTags",
                        ],
                        Effect: "Allow",
                        Resource: [`arn:aws:s3:::${name}-assets-${args.environment}-replica/*`],
                    }],
                }),
            }, { parent: this });

            new aws.s3.BucketReplicationConfig(`${name}-replication`, {
                bucket: this.bucket.id,
                role: replicationRole.arn,
                rules: [{
                    id: "replication-rule",
                    status: "Enabled",
                    destination: {
                        bucket: `arn:aws:s3:::${name}-assets-${args.environment}-replica`,
                        storageClass: "STANDARD",
                    },
                }],
            }, { parent: this });
        }

        // =========================================================================
        // RDS PostgreSQL: Deletion Protection + Backup Retention + Encryption
        // =========================================================================

        // Generate random password (stored in Pulumi state as secret)
        const dbPassword = new random.RandomPassword(`${name}-db-password`, {
            length: 32,
            special: true,
            overrideSpecial: "!#$%&*()-_=+[]{}<>:?",
        }, { parent: this });

        this.dbPassword = dbPassword.result;

        // Security group for RDS (private only)
        const dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            description: `Security group for ${name} RDS instance`,
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: ["10.0.0.0/8"], // Internal VPC CIDR only
                description: "PostgreSQL from internal network",
            }],
            egress: [{
                protocol: "-1",
                fromPort: 0,
                toPort: 0,
                cidrBlocks: ["0.0.0.0/0"],
                description: "Allow all outbound",
            }],
            tags: defaultTags,
        }, { parent: this });

        this.dbInstance = new aws.rds.Instance(`${name}-db`, {
            identifier: `${name}-db-${args.environment}`,
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: args.dbAllocatedStorage,
            storageType: "gp3",
            storageEncrypted: args.environment === "prod", // Encrypt in prod

            dbName: "appdb",
            username: "dbadmin",
            password: dbPassword.result,

            multiAz: args.dbMultiAz,
            publiclyAccessible: false, // Acceptance Criteria #2
            vpcSecurityGroupIds: [dbSecurityGroup.id],

            deletionProtection: true, // Acceptance Criteria #2
            skipFinalSnapshot: args.environment === "dev", // Keep snapshots in prod
            finalSnapshotIdentifier: args.environment === "prod" 
                ? `${name}-db-final-snapshot-${Date.now()}` 
                : undefined,

            backupRetentionPeriod: args.environment === "prod" ? 30 : 7, // >= 7 days
            backupWindow: "03:00-04:00",
            maintenanceWindow: "sun:04:00-sun:05:00",

            enabledCloudwatchLogsExports: ["postgresql", "upgrade"],

            tags: defaultTags,
        }, { parent: this });

        // Connection string as Pulumi secret (Acceptance Criteria #3)
        this.dbConnectionString = pulumi.all([
            this.dbInstance.endpoint,
            this.dbInstance.dbName,
            this.dbInstance.username,
            dbPassword.result,
        ]).apply(([endpoint, db, user, pass]) => 
            `postgresql://${user}:${pass}@${endpoint}/${db}`
        );

        // =========================================================================
        // IAM Role for Service Accounts (Least Privilege)
        // =========================================================================

        // Dev: Basic assume role policy
        // Prod: OIDC trust for Kubernetes service accounts (IRSA)
        const assumeRolePolicy = args.environment === "prod" && args.oidcProviderArn && args.oidcProviderUrl
            ? JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: {
                        Federated: args.oidcProviderArn,
                    },
                    Action: "sts:AssumeRoleWithWebIdentity",
                    Condition: {
                        StringEquals: {
                            [`${args.oidcProviderUrl}:sub`]: `system:serviceaccount:default:${name}-sa`,
                            [`${args.oidcProviderUrl}:aud`]: "sts.amazonaws.com",
                        },
                    },
                }],
            })
            : JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: {
                        Service: "ec2.amazonaws.com", // Fallback for dev
                    },
                    Action: "sts:AssumeRole",
                }],
            });

        this.serviceAccountRole = new aws.iam.Role(`${name}-sa-role`, {
            name: `${name}-sa-role-${args.environment}`,
            assumeRolePolicy: assumeRolePolicy,
            tags: defaultTags,
        }, { parent: this });

        // Least privilege policy: specific bucket, specific actions
        // Prod: No wildcards (Acceptance Criteria #4)
        const policyDocument = pulumi.all([this.bucket.arn]).apply(([bucketArn]) => {
            const baseActions = [
                "s3:GetObject",
                "s3:PutObject",
                "s3:DeleteObject",
                "s3:ListBucket",
            ];

            // Dev allows broader access for testing; prod is strictly limited
            const actions = args.environment === "prod" 
                ? baseActions 
                : [...baseActions, "s3:GetBucketLocation", "s3:ListAllMyBuckets"];

            return JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Sid: "AllowSpecificBucketAccess",
                    Effect: "Allow",
                    Action: actions,
                    Resource: [
                        bucketArn,
                        `${bucketArn}/*`,
                    ],
                }, {
                    Sid: "AllowRDSDescribe",
                    Effect: "Allow",
                    Action: [
                        "rds:DescribeDBInstances",
                        "rds:DescribeDBClusters",
                    ],
                    Resource: "*", // Describe requires wildcard, but no mutating actions
                }],
            });
        });

        new aws.iam.RolePolicy(`${name}-sa-policy`, {
            role: this.serviceAccountRole.id,
            policy: policyDocument,
        }, { parent: this });

        // Dev only: Create IAM user for programmatic access (legacy support)
        if (args.environment === "dev") {
            const iamUser = new aws.iam.User(`${name}-sa-user`, {
                name: `${name}-sa-${args.environment}`,
                tags: defaultTags,
            }, { parent: this });

            new aws.iam.UserPolicy(`${name}-user-policy`, {
                user: iamUser.name,
                policy: policyDocument,
            }, { parent: this });

            const accessKey = new aws.iam.AccessKey(`${name}-access-key`, {
                user: iamUser.name,
            }, { parent: this });

            // Export as secret
            this.registerOutputs({
                devAccessKeyId: accessKey.id,
                devSecretAccessKey: accessKey.secret,
            });
        }

        this.registerOutputs({
            bucketName: this.bucket.id,
            bucketArn: this.bucket.arn,
            dbEndpoint: this.dbInstance.endpoint,
            dbConnectionString: this.dbConnectionString,
            serviceAccountRoleArn: this.serviceAccountRole.arn,
        });
    }
}
