```typescript
// index.ts
import * as pulumi from "@pulumi/pulumi";
import { AppInfrastructure } from "./components/AppInfrastructure";

const config = new pulumi.Config();
const environment = config.require("environment") as "dev" | "prod";
const region = config.require("region");

// Environment-specific configuration
const infra = new AppInfrastructure("app", {
    environment: environment,
    region: region,

    // Database sizing per environment
    dbInstanceClass: config.get("dbInstanceClass") || 
        (environment === "prod" ? "db.t3.medium" : "db.t3.micro"),
    dbMultiAz: config.getBoolean("dbMultiAz") ?? (environment === "prod"),
    dbAllocatedStorage: config.getNumber("dbAllocatedStorage") || 
        (environment === "prod" ? 100 : 20),

    // Prod-only features
    enableReplication: environment === "prod",
    replicationRegion: "us-west-2",
    oidcProviderArn: config.get("oidcProviderArn"),
    oidcProviderUrl: config.get("oidcProviderUrl"),

    tags: {
        Project: "MyApp",
        Owner: "PlatformTeam",
    },
});

// Export outputs (marked as secret where sensitive)
export const bucketName = infra.bucket.id;
export const dbEndpoint = infra.dbInstance.endpoint;
export const serviceAccountRoleArn = infra.serviceAccountRole.arn;
export const dbConnectionString = pulumi.secret(infra.dbConnectionString);
